function auroraRibbon(id,path){return '<span class="aurora-wave wave-'+id+'" aria-hidden="true"><svg viewBox="0 0 180 180" fill="none"><defs><linearGradient id="aurora-'+id+'" x1="0" y1="0" x2="180" y2="180" gradientUnits="userSpaceOnUse"><stop stop-color="#57e3b3"/><stop offset=".45" stop-color="#5bafff"/><stop offset="1" stop-color="#ae84f2"/></linearGradient></defs><path d="'+path+'" stroke="url(#aurora-'+id+')" stroke-width="'+(id==='three'?25:35)+'" stroke-linecap="round"/></svg></span>';}
// Original aurora control; decorative colour stays inside this small surface.
function orbControl(){const server=selected(),status=connection==='on'?'Демо: подключено':connection==='pending'?'Демо: подключение…':'Не подключено',name=server?.name||'Выберите сервер';return `<section class="aurora-control connection" data-orb-state="${connection}" aria-label="Управление подключением"><div class="orb-status-live sr-only" role="status">${esc(status)}</div>${btn('connect','<span class="orb-halo" aria-hidden="true"></span><span class="orb-face" aria-hidden="true">'+auroraRibbon('one','M -25 105 C 40 150 36 20 95 55 S 180 125 215 20')+auroraRibbon('two','M -20 150 C 50 25 55 170 125 90 S 180 10 220 55')+auroraRibbon('three','M -20 45 C 40 115 80 5 125 85 S 180 160 220 95')+'<span class="orb-depth"></span></span><span class="orb-power" aria-hidden="true">'+icon('power')+'</span>','aurora-button',`aria-label="${esc((connection==='on'?'Демо: отключиться от ':'Демо: подключиться к ')+name)}" aria-pressed="${connection==='on'}" ${!server||connection==='pending'?'disabled':''}`)}<div class="orb-expanded" aria-hidden="true"><div class="status"><i></i>${status}</div><h2>${esc(name)}</h2>${server?'':'<small>Добавьте ссылку или подписку</small>'}</div></section>${connectionError?'<p class="error orb-error" role="alert">'+esc(connectionError)+'</p>':''}`;}
const homeWithoutOrb=home;home=function(){return homeWithoutOrb().replace(/<section class="card connection">[\s\S]*?<\/section>/,()=>orbControl());};
let lastOrbState='';
function syncOrb(){const button=root.querySelector('.aurora-button');if(button){button.style.width='176px';button.style.height='176px';}}
const renderWithoutOrb=render;render=function(){const frozen=lastOrbState==='on'&&connection==='off'&&typeof getComputedStyle==='function'?[...root.querySelectorAll('.aurora-wave')].map(el=>getComputedStyle(el).transform):null;renderWithoutOrb();syncOrb();if(frozen)root.querySelectorAll('.aurora-wave').forEach((el,i)=>el.style.transform=frozen[i]);else if(connection==='on')root.querySelectorAll('.aurora-wave').forEach(el=>el.style.removeProperty('transform'));document.documentElement.classList.toggle('aurora-paused',!!document.hidden);const button=root.querySelector('.aurora-button');if(lastOrbState&&lastOrbState!==connection)animateOnce('orb-transition',button,{scale:[.97,1.015,1]},{duration:.3,ease:'easeOut'});lastOrbState=connection;};
document.addEventListener('visibilitychange',()=>document.documentElement.classList.toggle('aurora-paused',!!document.hidden));
